import math

def check_constraint(q, K1):
    # Constraint: q * K1 <= a1**(-q) < q * K1 + 1
    # Since a1 = 1/K1 (if we choose a simple base), a1**(-q) = K1**q
    # Let's use a1 = 0.5, K1 = 2. The constraint is 2q <= 2^q < 2q + 1
    try:
        LHS = q * K1
        RHS = math.pow(2, q)
        limit = q * K1 + 1
        return LHS <= RHS < limit
    except OverflowError:
        return False

# Test some values of q for K1=2 (a1=0.5)
# We already found 0.5, 1, 2. Looking for a fourth one.
print("--- Testing values around 3 ---")
for q in [2.8, 2.9, 3.0, 3.1, 3.2]:
    if check_constraint(q, 2):
        print(f"q={q}: SATISFIES")
    else:
        print(f"q={q}: FAILED")

print("\n--- Testing values around 0.3 ---")
for q in [0.2, 0.3, 0.4]:
    if check_constraint(q, 2):
        print(f"q={q}: SATISFIES")
    else:
        print(f"q={q}: FAILED")

